//! The import against fixture folders of the launcher's old records (`testdata/import/appdata`:
//! `deployments/<lab>/<target>/` beside the labs they belong to) and the run manifests each lab
//! runs from now (`testdata/import/manifests`, shaped as Isoloom writes them; the Proxmox lab's
//! is generated by Isoloom during the import). The runner is a real one on a temporary home: a
//! takeover runs no tool.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

use isothrum_runner::isoloom_manifest::Cloud;
use isothrum_runner::{RunRecord, RunState, RunnerConfig};

use super::*;

const FIXTURES: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/src/runtime/isothrum/testdata/import");

/// Each cloud lab of the fixture and the manifest it runs from now.
const MANIFESTS: [(&str, &str, &str); 4] = [
    ("web", "cloud-vm/aws", "cloud-vm-aws"),
    ("shop", "cloud-docker/gcp", "cloud-docker-gcp"),
    ("portal", "cloud-vm/azure", "cloud-vm-azure"),
    ("bucket", "cloud-services", "cloud-services-aws"),
];

/// A copy of the fixture's app data folder, the runner's home too.
struct AppData {
    base: PathBuf,
    runner: Runner,
}

impl AppData {
    fn new() -> AppData {
        let base = std::env::temp_dir().join(format!("cyberctf-import-{}", rand::random::<u32>()));
        copy_tree(&Path::new(FIXTURES).join("appdata"), &base);
        for (id, target, manifest) in MANIFESTS {
            let to = base.join("labs").join(id).join(".isoloom").join(target);
            std::fs::create_dir_all(&to).unwrap();
            std::fs::copy(Path::new(FIXTURES).join("manifests").join(format!("{manifest}.run.json")), to.join("run.json")).unwrap();
        }
        let runner = Runner::new(RunnerConfig::new(&base)).unwrap();
        AppData { base, runner }
    }

    /// Every deployment handed over to the runner as the predicate `runs` allows, none busy.
    async fn import(&self, runs: impl Fn(Provider, Runtime) -> bool) -> BTreeMap<String, Outcome> {
        let all = import_all(&self.runner, &self.base, runs, |_| Some(())).await;
        all.into_iter().map(|(d, o)| (format!("{}/{}", d.id, d.provider.id()), o)).collect()
    }

    fn state(&self, id: &str, target: &str) -> PathBuf {
        self.base.join("deployments").join(id).join(target)
    }

    fn run_dir(&self, id: &str) -> PathBuf {
        self.base.join("runs").join(format!("cyberctf-{id}"))
    }

    fn record(&self, id: &str) -> RunRecord {
        let name = format!("cyberctf-{id}");
        self.runner.runs().unwrap().into_iter().find(|r| r.name.as_str() == name).unwrap_or_else(|| panic!("no run {name}"))
    }
}

impl Drop for AppData {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.base);
    }
}

fn copy_tree(from: &Path, to: &Path) {
    std::fs::create_dir_all(to).unwrap();
    for entry in std::fs::read_dir(from).unwrap().flatten() {
        let target = to.join(entry.file_name());
        if entry.path().is_dir() {
            copy_tree(&entry.path(), &target);
        } else {
            std::fs::copy(entry.path(), target).unwrap();
        }
    }
}

/// Every kind of deployment, as task 2's runner runs them all.
fn every_kind(_: Provider, _: Runtime) -> bool {
    true
}

fn params(r: &RunRecord) -> Vec<(&str, &str)> {
    r.params.iter().map(|(k, v)| (k.as_str(), v.as_str())).collect()
}

fn outcome<'a>(all: &'a BTreeMap<String, Outcome>, key: &str) -> &'a Outcome {
    all.get(key).unwrap_or_else(|| panic!("no deployment {key}: {all:?}"))
}

#[tokio::test]
async fn an_aws_vm_lab_becomes_a_ready_run_with_its_region_firewall_account_and_auto_stop() {
    let app = AppData::new();
    assert!(left_on_launcher(&app.base, "web", Provider::Aws), "before: the launcher's own");
    let all = app.import(every_kind).await;
    assert!(matches!(outcome(&all, "web/aws"), Outcome::Imported), "{all:?}");
    let r = app.record("web");
    assert_eq!((r.state, r.cloud, r.host_label.as_deref(), r.expires_at), (RunState::Ready, Some(Cloud::Aws), Some("aws-main"), Some(4_102_444_800)));
    assert_eq!(params(&r), [("allowed_cidr", "203.0.113.7/32"), ("region", "eu-west-3")], "the launcher's key and key file aren't params");
    assert!(r.started_at.is_some(), "applied when its record was written");
    assert!(app.run_dir("web").join("terraform.tfstate").is_file() && app.run_dir("web").join("terraform.tfstate.backup").is_file());
    assert!(!app.state("web", "aws").join("terraform.tfstate").exists(), "moved, never copied");
    assert_eq!(std::fs::read_to_string(app.state("web", "aws").join("imported")).unwrap(), "cyberctf-web");
    assert!(!left_on_launcher(&app.base, "web", Provider::Aws), "after: the runner's");
}

#[tokio::test]
async fn a_gcp_docker_lab_keeps_its_project_and_another_deployment_of_it_stays_the_launchers() {
    let app = AppData::new();
    let all = app.import(every_kind).await;
    assert!(matches!(outcome(&all, "shop/gcp"), Outcome::Imported), "the current one first, though `aws` sorts before it: {all:?}");
    assert!(matches!(outcome(&all, "shop/aws"), Outcome::Left(Left::RunExists)), "{all:?}");
    let r = app.record("shop");
    assert_eq!((r.cloud, r.target), (Some(Cloud::Gcp), isothrum_runner::isoloom_manifest::Target::CloudDocker));
    assert_eq!(params(&r), [("allowed_cidr", "203.0.113.7/32"), ("project", "cyberctf-labs-1a2b"), ("region", "europe-west1")]);
    assert!(app.state("shop", "aws").join("terraform.tfstate").is_file() && left_on_launcher(&app.base, "shop", Provider::Aws));
}

#[tokio::test]
async fn an_azure_lab_takes_its_subscription_from_the_kept_environment() {
    let app = AppData::new();
    let all = app.import(every_kind).await;
    assert!(matches!(outcome(&all, "portal/azure"), Outcome::Imported), "{all:?}");
    let r = app.record("portal");
    assert_eq!(params(&r), [("allowed_cidr", "203.0.113.7/32"), ("region", "westeurope"), ("subscription_id", "00000000-1111-2222-3333-444444444444")]);
    assert_eq!(r.host_label.as_deref(), Some("azure-main"));
}

#[tokio::test]
async fn a_cloud_services_lab_takes_its_launch_values_into_its_run() {
    let app = AppData::new();
    let all = app.import(every_kind).await;
    assert!(matches!(outcome(&all, "bucket/aws"), Outcome::Imported), "{all:?}");
    let r = app.record("bucket");
    assert_eq!((r.target, r.expires_at), (isothrum_runner::isoloom_manifest::Target::CloudServices, Some(4_102_444_800)));
    assert_eq!(params(&r).len(), 0, "its manifest takes no region: {:?}", r.params);
    let inputs = std::fs::read_to_string(app.run_dir("bucket").join("inputs.tfvars.json")).unwrap();
    assert!(inputs.contains("203.0.113.7/32"), "{inputs}");
    assert!(!app.state("bucket", "aws").join("inputs.tfvars.json").exists());
}

#[tokio::test]
async fn a_proxmox_lab_whose_files_predate_manifests_is_generated_then_taken_in_its_slot() {
    let app = AppData::new();
    assert!(!app.base.join("labs/pve/.isoloom/proxmox/run.json").exists());
    let all = app.import(every_kind).await;
    assert!(matches!(outcome(&all, "pve/proxmox"), Outcome::Imported), "{all:?}");
    let r = app.record("pve");
    assert_eq!((r.slot, r.host_label.as_deref(), r.cloud), (Some(1), Some("pve-1"), None));
    let p = params(&r);
    for kept in [("datastore", "local-lvm"), ("node", "pve-lab"), ("proxmox_endpoint", "https://10.0.0.5:8006/"), ("uplink_bridge", "vmbr1")] {
        assert!(p.contains(&kept), "{kept:?} in {p:?}");
    }
    assert!(!r.params.contains_key("ssh_public_key"), "the runner sets the key");
}

#[tokio::test]
async fn a_broken_or_empty_state_is_left_and_a_lab_no_longer_installed_is_said_once() {
    let app = AppData::new();
    let all = app.import(every_kind).await;
    assert!(matches!(outcome(&all, "broken/aws"), Outcome::Left(Left::Empty)), "{all:?}");
    assert!(matches!(outcome(&all, "empty/aws"), Outcome::Left(Left::Empty)), "{all:?}");
    assert!(matches!(outcome(&all, "gone/aws"), Outcome::Failed { error: ImportError::LabGone(_), new: true }), "{all:?}");
    assert!(app.state("gone", "aws").join("terraform.tfstate").is_file() && left_on_launcher(&app.base, "gone", Provider::Aws), "kept for the launcher's path");
    let again = app.import(every_kind).await;
    assert!(matches!(outcome(&again, "gone/aws"), Outcome::Failed { new: false, .. }), "the same reason isn't news: {again:?}");
}

#[tokio::test]
async fn a_second_import_changes_nothing() {
    let app = AppData::new();
    app.import(every_kind).await;
    let before = app.runner.runs().unwrap();
    let again = app.import(every_kind).await;
    for key in ["web/aws", "shop/gcp", "portal/azure", "bucket/aws", "pve/proxmox"] {
        assert!(matches!(outcome(&again, key), Outcome::Left(Left::Imported)), "{key}: {again:?}");
    }
    assert_eq!(app.runner.runs().unwrap(), before);
}

#[tokio::test]
async fn only_what_the_runner_runs_is_handed_over_and_a_busy_lab_waits() {
    let app = AppData::new();
    let all = app.import(crate::runtime::launch::runner_runs_on).await;
    assert!(matches!(outcome(&all, "pve/proxmox"), Outcome::Imported), "{all:?}");
    assert!(matches!(outcome(&all, "web/aws"), Outcome::Left(Left::NotRunners)), "{all:?}");
    assert!(app.state("web", "aws").join("terraform.tfstate").is_file());
    let busy = import_all(&app.runner, &app.base, every_kind, |id: &str| (id != "web").then_some(())).await;
    let web = busy.iter().find(|(d, _)| d.id == "web").map(|(_, o)| o);
    assert!(matches!(web, Some(Outcome::Left(Left::Busy))), "{busy:?}");
}
